<?php
declare(strict_types=1);require_once __DIR__.'/operations.php';if(!user_has_role('owner_admin')){http_response_code(403);exit('Owner access required.');}$s=new \Hambelela\EPI\PerformanceScore(db());$cards=$s->scorecards();$rules=$s->rules();$pageTitle='EPI Scoring Settings | '.APP_NAME;$activeApp='kpi';include BASE_PATH.'/shared/header.php';include BASE_PATH.'/shared/sidebar.php';function epi9se($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><main class="workspace module epi-page"><section class="module-header"><div><p class="eyebrow">EPI Phase 9</p><h1>Scoring Settings Verification</h1><p>Owner-only effective-dated scorecards and rules. Values are integer hundredths; no floating-point scoring is used.</p></div></section><section class="section-card" style="padding:18px;overflow:auto"><h2>Scorecards</h2><table class="ops-table"><thead><tr><th>Name</th><th>Role</th><th>Version</th><th>Effective</th><th>Categories</th><th>Weight total</th><th>Validation</th></tr></thead><tbody><?php foreach($cards as$r):?><tr><td><?=epi9se($r['scorecard_name'])?></td><td><?=epi9se($r['role_key']?:'General')?></td><td><?=(int)$r['version']?></td><td><?=epi9se($r['effective_from'])?></td><td><?=(int)$r['category_count']?></td><td><?=number_format(((int)$r['weight_total_hundredths'])/100,2)?>%</td><td><?=(int)$r['weight_total_hundredths']===10000?'Valid':'Invalid: must equal 100%'?></td></tr><?php endforeach;?></tbody></table></section><section class="section-card" style="padding:18px;overflow:auto"><h2>Performance rules</h2><p>Rules are inactive until explicitly created and owner-approved. Evidence without a matching active rule cannot change a score.</p><table class="ops-table"><thead><tr><th>Rule</th><th>Module</th><th>Category</th><th>Kind</th><th>Impact</th><th>Effective</th><th>Owner confirmation</th></tr></thead><tbody><?php if(!$rules):?><tr><td colspan="7">No performance rules have been approved. This is safe: employee scores remain unchanged.</td></tr><?php else:foreach($rules as$r):?><tr><td><?=epi9se($r['rule_name'])?></td><td><?=epi9se($r['module'])?></td><td><?=epi9se($r['category_key'])?></td><td><?=epi9se($r['rule_kind'])?></td><td><?=number_format(((int)$r['impact_hundredths'])/100,2)?></td><td><?=epi9se($r['effective_from'])?></td><td><?=!empty($r['owner_confirmation_required'])?'Required':'Not required'?></td></tr><?php endforeach;endif;?></tbody></table></section><p><a href="epi-scoring-performance.php">Back to scoring verification</a></p></main><?php include BASE_PATH.'/shared/footer.php';?>
